package main

import (
	"os"
	"path/filepath"
)

const contract = `{"openapi":"3.0.3","info":{"title":"Primer Tasks","version":"1.0.0"},"paths":{"/auth/session":{"get":{"responses":{"200":{"description":"session","content":{"application/json":{"schema":{"type":"object","properties":{"subjectRef":{"type":"string"},"tenantId":{"type":"string"}}}}}}}}},"/auth/logout":{"post":{"responses":{"200":{"description":"signed out","content":{"application/json":{"schema":{"type":"object","properties":{"status":{"type":"string"}}}}}}}}},"/students":{"get":{"parameters":[{"name":"q","in":"query","schema":{"type":"string"}},{"name":"limit","in":"query","schema":{"type":"integer"}},{"name":"offset","in":"query","schema":{"type":"integer"}}],"responses":{"200":{"description":"student page","content":{"application/json":{"schema":{"$ref":"#/components/schemas/StudentPage"}}}}}},"post":{"requestBody":{"required":true,"content":{"application/json":{"schema":{"$ref":"#/components/schemas/CreateStudent"}}}},"responses":{"201":{"description":"student","content":{"application/json":{"schema":{"$ref":"#/components/schemas/Student"}}}}}}},"/students/{id}":{"parameters":[{"name":"id","in":"path","required":true,"schema":{"type":"string"}}],"get":{"responses":{"200":{"description":"student","content":{"application/json":{"schema":{"$ref":"#/components/schemas/Student"}}}}}},"patch":{"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/UpdateStudent"}}}},"responses":{"200":{"description":"student","content":{"application/json":{"schema":{"$ref":"#/components/schemas/Student"}}}}}},"delete":{"responses":{"204":{"description":"archived"}}}},"/students/{id}/pairing":{"parameters":[{"name":"id","in":"path","required":true,"schema":{"type":"string"}}],"post":{"responses":{"200":{"description":"pairing","content":{"application/json":{"schema":{"$ref":"#/components/schemas/Pairing"}}}}}}},"/student/pair":{"post":{"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/Pair"}}}},"responses":{"200":{"description":"paired","content":{"application/json":{"schema":{"type":"object","properties":{"studentId":{"type":"string"}}}}}}}}},"/student/profile":{"get":{"responses":{"200":{"description":"profile","content":{"application/json":{"schema":{"$ref":"#/components/schemas/Student"}}}}}}},"/student/checklist":{"get":{"responses":{"200":{"description":"checklist","content":{"application/json":{"schema":{"$ref":"#/components/schemas/Checklist"}}}}}}}},"components":{"schemas":{"Student":{"type":"object","required":["id","displayName","createdAt"],"properties":{"id":{"type":"string"},"displayName":{"type":"string"},"createdAt":{"type":"string","format":"date-time"},"archivedAt":{"type":"string","format":"date-time","nullable":true}}},"StudentPage":{"type":"object","required":["items","totalCount","limit","offset"],"properties":{"items":{"type":"array","items":{"$ref":"#/components/schemas/Student"}},"totalCount":{"type":"integer"},"limit":{"type":"integer"},"offset":{"type":"integer"}}},"Pairing":{"type":"object","required":["pairingId","code","expiresAt","qrPayload"],"properties":{"pairingId":{"type":"string"},"code":{"type":"string"},"expiresAt":{"type":"string","format":"date-time"},"qrPayload":{"type":"string"}}},"Checklist":{"type":"object","required":["items"],"properties":{"items":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string"},"title":{"type":"string"},"description":{"type":"string"},"status":{"type":"string"}}}}}},"CreateStudent":{"type":"object","required":["displayName"],"properties":{"displayName":{"type":"string"}}},"UpdateStudent":{"type":"object","required":["displayName"],"properties":{"displayName":{"type":"string"}}},"Pair":{"type":"object","required":["code"],"properties":{"code":{"type":"string"}}}}}}`

func main() {
	out := os.Getenv("TASKS_OPENAPI_OUT")
	if out == "" {
		out = "build/openapi.yaml"
	}
	_ = os.MkdirAll(filepath.Dir(out), 0700)
	if err := os.WriteFile(out, []byte(contract), 0600); err != nil {
		panic(err)
	}
}
